import pg from "pg";

export const DATABASE_URL =
  process.env.DATABASE_URL ?? "postgres://postgres:eksperimen@localhost:5433/eksperimen";
export const pool = new pg.Pool({ connectionString: DATABASE_URL, max: 10 });

export async function tx<T>(fn: (c: pg.PoolClient) => Promise<T>): Promise<T> {
  const c = await pool.connect();
  try {
    await c.query("BEGIN");
    const result = await fn(c);
    await c.query("COMMIT");
    return result;
  } catch (e) {
    await c.query("ROLLBACK");
    throw e;
  } finally {
    c.release();
  }
}

import { createHash, createHmac } from "node:crypto";

export type Variant = { key: string; weight: number }; // bobot dalam basis poin, total 10000
export type FlagConfig = {
  key: string;
  status: "draft" | "running" | "stopped";
  killed: boolean;
  salt: string;
  traffic_bp: number;
  variants: Variant[];
  default_variant: string;
};
export type Assignment = { variant: string; inExperiment: boolean };

export const BUCKETS = 10_000;

// Bucket 0..9999. Input sama -> bucket sama, di proses dan mesin mana pun.
// ponytail: bias modulo 2^32 % 10000 sekitar 0,0002%, jauh di bawah derau statistik.
export function bucket(salt: string, unit: string): number {
  return createHash("sha256").update(`${salt}:${unit}`).digest().readUInt32BE(0) % BUCKETS;
}

// Id pseudonim: HMAC dari user id asli. Server eksperimen tidak pernah melihat id asli/email.
export function pseudonym(secret: string, userId: string): string {
  return createHmac("sha256", secret).update(userId).digest("base64url").slice(0, 22);
}

export function assign(flag: FlagConfig, unit: string): Assignment {
  const off = { variant: flag.default_variant, inExperiment: false };
  if (flag.killed || flag.status !== "running") return off;
  // Hash 1: ikut eksperimen atau tidak. Menaikkan traffic hanya MENAMBAH unit baru.
  if (bucket(`${flag.salt}:traffic`, unit) >= flag.traffic_bp) return off;
  // Hash 2, independen dari hash 1: memilih varian. Tidak terpengaruh perubahan traffic.
  let b = bucket(`${flag.salt}:variant`, unit);
  for (const v of flag.variants) {
    if (b < v.weight) return { variant: v.key, inExperiment: true };
    b -= v.weight;
  }
  return off; // total bobot != 10000; validasi admin mencegah ini
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { assign, type FlagConfig } from "../src/hash.ts";

const flag: FlagConfig = {
  key: "tombol-checkout", status: "running", killed: false, salt: "a1b2c3d4", traffic_bp: 1000,
  variants: [{ key: "control", weight: 5000 }, { key: "treatment", weight: 5000 }], default_variant: "control",
};
const full = { ...flag, traffic_bp: 10_000 };
const units = Array.from({ length: 20_000 }, (_, i) => `unit-${i}`);
const share = (f: FlagConfig, v: string) => units.filter((u) => assign(f, u).variant === v).length / units.length;

test("deterministik: unit yang sama selalu mendapat varian yang sama", () => {
  for (const u of units.slice(0, 200)) assert.deepEqual(assign(flag, u), assign(flag, u));
});

test("pembagian mengikuti bobot (50/50 +- 1,5 poin)", () => {
  assert.ok(Math.abs(share(full, "treatment") - 0.5) < 0.015);
});

test("menaikkan traffic 10% -> 20% tidak memindahkan unit lama", () => {
  const wider = { ...flag, traffic_bp: 2000 };
  let before = 0, after = 0;
  for (const u of units) {
    const a = assign(flag, u), b = assign(wider, u);
    if (a.inExperiment) { before++; assert.deepEqual(b, a, `${u} pindah varian`); }
    if (b.inExperiment) after++;
  }
  assert.ok(Math.abs(before / units.length - 0.1) < 0.01 && Math.abs(after / units.length - 0.2) < 0.01);
});

test("mengubah bobot 50/50 -> 70/30 memindahkan sekitar 20% unit", () => {
  const skew = { ...full, variants: [{ key: "control", weight: 7000 }, { key: "treatment", weight: 3000 }] };
  const moved = units.filter((u) => assign(full, u).variant !== assign(skew, u).variant).length / units.length;
  assert.ok(Math.abs(moved - 0.2) < 0.015, `pindah ${moved}`);
});

test("salt lain = pengacakan baru yang tidak berkorelasi", () => {
  const other = { ...full, salt: "e5f6a7b8" };
  const same = units.filter((u) => assign(full, u).variant === assign(other, u).variant).length / units.length;
  assert.ok(Math.abs(same - 0.5) < 0.02);
});

test("kill switch atau status bukan running -> default dan tidak dihitung exposure", () => {
  for (const f of [{ ...full, killed: true }, { ...full, status: "stopped" as const }]) {
    assert.deepEqual(assign(f, "unit-1"), { variant: "control", inExperiment: false });
  }
});

import type { IncomingMessage, ServerResponse } from "node:http";

export class HttpError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

export function check(ok: unknown, message: string, status = 422): asserts ok {
  if (!ok) throw new HttpError(status, message);
}

const KEY = /^[a-z0-9][a-z0-9-]{1,62}$/;
export const isKey = (s: unknown): s is string => typeof s === "string" && KEY.test(s);

export async function readJson(req: IncomingMessage, limit = 1_000_000): Promise<any> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const c of req) {
    size += c.length;
    if (size > limit) throw new HttpError(413, "body terlalu besar (maks 1 MB)");
    chunks.push(c);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString("utf8") || "null");
  } catch {
    throw new HttpError(400, "JSON tidak valid");
  }
}

export function send(res: ServerResponse, status: number, body?: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, body === undefined ? headers : { "content-type": "application/json", ...headers });
  res.end(body === undefined ? undefined : JSON.stringify(body));
}

import { randomBytes } from "node:crypto";
import type pg from "pg";
import { pool, tx } from "./db.ts";
import type { FlagConfig, Variant } from "./hash.ts";
import { HttpError, check, isKey } from "./http.ts";

export type Metric = {
  key: string;          // nama metrik di laporan
  event: string;        // nama event conversion yang dihitung
  type: "binomial" | "mean"; // binomial: unit punya >= 1 event; mean: jumlah value per unit
  role: "primary" | "secondary" | "guardrail";
  better: "higher" | "lower";
};
export type Flag = FlagConfig & { description: string; metrics: Metric[]; version: string; updated_at: string };

const COLS = "key, description, status, killed, salt, traffic_bp, variants, default_variant, metrics, version::text, updated_at";

const isMetric = (m: any): m is Metric =>
  isKey(m?.key) && isKey(m.event) && ["binomial", "mean"].includes(m.type) &&
  ["primary", "secondary", "guardrail"].includes(m.role) && ["higher", "lower"].includes(m.better);

export function parseFlagInput(b: any) {
  check(b && typeof b === "object", "body harus objek JSON");
  const { description = "", status = "draft", traffic_bp, variants, default_variant, metrics = [] } = b;
  check(typeof description === "string" && description.length <= 500, "description maks 500 karakter");
  check(["draft", "running", "stopped"].includes(status), "status: draft | running | stopped");
  check(Number.isInteger(traffic_bp) && traffic_bp >= 0 && traffic_bp <= 10_000, "traffic_bp bilangan bulat 0..10000");
  check(Array.isArray(variants) && variants.length >= 1 && variants.length <= 10, "variants berisi 1..10 varian");
  for (const v of variants) check(isKey(v?.key) && Number.isInteger(v.weight) && v.weight >= 0, "setiap varian butuh key dan weight bulat");
  check(new Set(variants.map((v: Variant) => v.key)).size === variants.length, "key varian harus unik");
  check(variants.reduce((s: number, v: Variant) => s + v.weight, 0) === 10_000, "total weight harus 10000");
  check(variants.some((v: Variant) => v.key === default_variant), "default_variant harus salah satu varian");
  check(Array.isArray(metrics) && metrics.length <= 20 && metrics.every(isMetric), "metrics tidak valid");
  return {
    description, status, traffic_bp, default_variant,
    variants: variants.map(({ key, weight }: Variant) => ({ key, weight })),
    metrics: metrics.map(({ key, event, type, role, better }: Metric) => ({ key, event, type, role, better })),
  } as Pick<Flag, "description" | "status" | "traffic_bp" | "variants" | "default_variant" | "metrics">;
}

export async function listFlags(): Promise<Flag[]> {
  return (await pool.query(`SELECT ${COLS} FROM flags ORDER BY key`)).rows;
}

export async function auditFor(key: string) {
  const { rows } = await pool.query(
    "SELECT id::text, at, actor, action, reason, before, after FROM audit_log WHERE flag_key = $1 ORDER BY id DESC LIMIT 100",
    [key]);
  return rows;
}

async function locked(c: pg.PoolClient, key: string): Promise<Flag | undefined> {
  return (await c.query(`SELECT ${COLS} FROM flags WHERE key = $1 FOR UPDATE`, [key])).rows[0];
}

// Satu transaksi: simpan flag, tulis audit, kabari SDK. NOTIFY baru terkirim saat COMMIT.
async function save(c: pg.PoolClient, actor: string, action: string, reason: string,
                    before: Flag | undefined, f: Omit<Flag, "version" | "updated_at">): Promise<Flag> {
  const { rows: [after] } = await c.query(
    `INSERT INTO flags (key, description, status, killed, salt, traffic_bp, variants, default_variant, metrics, version)
     VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, nextval('config_version'))
     ON CONFLICT (key) DO UPDATE SET description = $2, status = $3, killed = $4, traffic_bp = $6, variants = $7,
       default_variant = $8, metrics = $9, version = EXCLUDED.version, updated_at = now()
     RETURNING ${COLS}`,
    [f.key, f.description, f.status, f.killed, f.salt, f.traffic_bp, JSON.stringify(f.variants),
     f.default_variant, JSON.stringify(f.metrics)]);
  await c.query(
    "INSERT INTO audit_log (actor, action, flag_key, reason, before, after) VALUES ($1, $2, $3, $4, $5, $6)",
    [actor, action, f.key, reason, before ? JSON.stringify(before) : null, JSON.stringify(after)]);
  await c.query("SELECT pg_notify('flags', $1)", [after.version]);
  return after;
}

const layout = (vs: Variant[]) => vs.map((v) => `${v.key}:${v.weight}`).join(",");

export async function putFlag(actor: string, key: string, body: any): Promise<Flag> {
  check(isKey(key), "key flag: huruf kecil, angka, dan tanda hubung (2-63 karakter)");
  const input = parseFlagInput(body);
  const reason = typeof body.reason === "string" ? body.reason.slice(0, 500) : "";
  return tx(async (c) => {
    const before = await locked(c, key);
    if (before?.status === "running" && layout(before.variants) !== layout(input.variants)) {
      throw new HttpError(409, "eksperimen sedang berjalan: mengubah varian atau bobot memindahkan unit antar varian. " +
        "Hentikan, lalu buat flag baru (mis. " + key + "-v2).");
    }
    return save(c, actor, before ? "update" : "create", reason, before, {
      key, ...input, killed: before?.killed ?? false, salt: before?.salt ?? randomBytes(8).toString("hex"),
    });
  });
}

// Kill switch: semua unit langsung mendapat default_variant, exposure berhenti dicatat.
export async function setKilled(actor: string, key: string, killed: boolean, reason: unknown): Promise<Flag> {
  check(typeof reason === "string" && reason.trim().length >= 3, "alasan (reason) wajib diisi");
  return tx(async (c) => {
    const before = await locked(c, key);
    if (!before) throw new HttpError(404, "flag tidak ditemukan");
    return save(c, actor, killed ? "kill" : "unkill", reason, before, { ...before, killed });
  });
}

import assert from "node:assert/strict";
import { after, test } from "node:test";
import { pool } from "../src/db.ts";
import { auditFor, putFlag, setKilled } from "../src/flags.ts";

after(() => pool.end());
const key = `tes-flags-${Date.now()}`;
const body = {
  status: "running", traffic_bp: 1000, default_variant: "control", reason: "uji",
  variants: [{ key: "control", weight: 5000 }, { key: "treatment", weight: 5000 }],
};

test("membuat flag: salt dibuat server dan audit tercatat", async () => {
  const f = await putFlag("ani", key, { ...body, salt: "dari-klien" });
  assert.match(f.salt, /^[0-9a-f]{16}$/);
  const [row] = await auditFor(key);
  assert.equal(row.action, "create");
  assert.equal(row.actor, "ani");
  assert.equal(row.before, null);
});

test("validasi: total bobot harus 10000", async () => {
  await assert.rejects(putFlag("ani", `${key}-x`, { ...body, variants: [{ key: "a", weight: 5000 }] }), { status: 422 });
});

test("menaikkan traffic boleh, salt dan varian tetap", async () => {
  const before = (await auditFor(key))[0].after;
  const f = await putFlag("ani", key, { ...body, traffic_bp: 2000 });
  assert.equal(f.salt, before.salt);
  assert.equal(f.traffic_bp, 2000);
  assert.ok(Number(f.version) > Number(before.version));
});

test("mengubah bobot eksperimen yang berjalan ditolak 409", async () => {
  const skew = [{ key: "control", weight: 7000 }, { key: "treatment", weight: 3000 }];
  await assert.rejects(putFlag("ani", key, { ...body, variants: skew }), { status: 409 });
});

test("kill switch wajib alasan dan masuk audit", async () => {
  await assert.rejects(setKilled("budi", key, true, ""), { status: 422 });
  const f = await setKilled("budi", key, true, "error checkout naik");
  assert.equal(f.killed, true);
  const [row] = await auditFor(key);
  assert.deepEqual([row.action, row.actor, row.reason], ["kill", "budi", "error checkout naik"]);
});

test("audit_log tidak bisa diubah atau dihapus", async () => {
  await assert.rejects(pool.query("UPDATE audit_log SET actor = 'x' WHERE flag_key = $1", [key]), /hanya boleh INSERT/);
  await assert.rejects(pool.query("DELETE FROM audit_log WHERE flag_key = $1", [key]), /hanya boleh INSERT/);
});

import { pool } from "./db.ts";
import { check, isKey } from "./http.ts";

export const MAX_BATCH = 500;
const MAX_AGE_MS = 30 * 86_400_000;  // event lebih tua dari 30 hari ditolak
const MAX_SKEW_MS = 5 * 60_000;      // jam klien boleh maju 5 menit
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const UNIT = /^[A-Za-z0-9_-]{8,64}$/; // bentuk id pseudonim; '@' dan '.' (email) otomatis ditolak

export type EventRow = {
  event_id: string; ts: string; kind: "exposure" | "conversion"; unit: string;
  flag_key: string | null; variant: string | null; metric: string | null; value: number;
};

// Seluruh batch ditolak kalau satu event salah: klien tahu persis apa yang harus diperbaiki.
export function validateBatch(body: any, now = Date.now()): EventRow[] {
  check(body && Array.isArray(body.events), "body harus {\"events\": [...]}");
  check(body.events.length >= 1 && body.events.length <= MAX_BATCH, `1..${MAX_BATCH} event per batch`);
  return body.events.map((e: any, i: number): EventRow => {
    const at = `events[${i}]`, t = Date.parse(e?.ts);
    check(typeof e?.event_id === "string" && UUID.test(e.event_id), `${at}.event_id harus UUID`);
    check(Number.isFinite(t) && t > now - MAX_AGE_MS && t < now + MAX_SKEW_MS, `${at}.ts di luar jendela (30 hari ke belakang, 5 menit ke depan)`);
    check(typeof e.unit === "string" && UNIT.test(e.unit), `${at}.unit harus id pseudonim 8-64 karakter [A-Za-z0-9_-], bukan email atau data pribadi`);
    check(e.value === undefined || Number.isFinite(e.value), `${at}.value harus angka`);
    if (e.kind === "exposure") check(isKey(e.flag_key) && isKey(e.variant), `${at}: exposure butuh flag_key dan variant`);
    else check(e.kind === "conversion" && isKey(e.metric), `${at}: kind harus exposure atau conversion (conversion butuh metric)`);
    const exp = e.kind === "exposure";
    return {
      event_id: e.event_id.toLowerCase(), ts: new Date(t).toISOString(), kind: e.kind, unit: e.unit,
      flag_key: exp ? e.flag_key : null, variant: exp ? e.variant : null, metric: exp ? null : e.metric, value: e.value ?? 1,
    };
  });
}

// Satu INSERT untuk seluruh batch. Duplikat (event_id, ts) dilewati: kirim ulang aman.
export async function insertEvents(events: EventRow[]): Promise<number> {
  const { rowCount } = await pool.query(
    `INSERT INTO events (event_id, ts, kind, unit, flag_key, variant, metric, value)
     SELECT event_id, ts, kind, unit, flag_key, variant, metric, value
     FROM jsonb_to_recordset($1::jsonb) AS x(event_id uuid, ts timestamptz, kind text, unit text,
                                              flag_key text, variant text, metric text, value float8)
     ON CONFLICT DO NOTHING`,
    [JSON.stringify(events)]);
  return rowCount ?? 0;
}

import { createHash, timingSafeEqual } from "node:crypto";
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import pg from "pg";
import { DATABASE_URL } from "./db.ts";
import { auditFor, listFlags, putFlag, setKilled } from "./flags.ts";
import { HttpError, readJson, send } from "./http.ts";
import { insertEvents, validateBatch } from "./ingest.ts";

const sha = (s: string) => createHash("sha256").update(s).digest();
const SDK_KEY = sha(process.env.SDK_KEY ?? "sdk-dev-key");
// ADMIN_TOKENS="ani=token-panjang-1,budi=token-panjang-2": nama dipakai sebagai actor di audit log.
const ADMINS = (process.env.ADMIN_TOKENS ?? "dev=admin-dev-token").split(",").map((pair) => {
  const [name, token] = pair.split("=");
  return { name, digest: sha(token ?? "") };
});

const bearer = (req: IncomingMessage) => sha((req.headers.authorization ?? "").replace(/^Bearer /, ""));
function adminActor(req: IncomingMessage): string {
  const d = bearer(req);
  const admin = ADMINS.find((a) => timingSafeEqual(a.digest, d));
  if (!admin) throw new HttpError(401, "token admin tidak valid");
  return admin.name;
}
function requireSdk(req: IncomingMessage): void {
  if (!timingSafeEqual(bearer(req), SDK_KEY)) throw new HttpError(401, "SDK key tidak valid");
}

// Hanya kolom yang dibutuhkan SDK untuk evaluasi. Metrik dan deskripsi tetap di server.
const forSdk = (f: Awaited<ReturnType<typeof listFlags>>[number]) => ({
  key: f.key, status: f.status, killed: f.killed, salt: f.salt, traffic_bp: f.traffic_bp,
  variants: f.variants, default_variant: f.default_variant,
});

const streams = new Set<ServerResponse>();

// LISTEN di koneksi khusus. Setiap instance server menerima NOTIFY lalu meneruskannya ke SDK via SSE.
export async function listenForChanges(): Promise<pg.Client> {
  const client = new pg.Client({ connectionString: DATABASE_URL });
  client.on("error", (e) => { console.error("koneksi LISTEN putus, keluar:", e.message); process.exit(1); });
  client.on("notification", (n) => {
    for (const res of streams) res.write(`event: flags\ndata: ${n.payload}\n\n`);
  });
  await client.connect();
  await client.query("LISTEN flags");
  return client;
}
setInterval(() => { for (const res of streams) res.write(": ping\n\n"); }, 25_000).unref();

export function createApp() {
  return createServer(async (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    const p = url.pathname, m = req.method;
    try {
      if (m === "GET" && p === "/healthz") return send(res, 200, { ok: true });

      if (p.startsWith("/sdk/") || p === "/events") requireSdk(req);
      if (m === "GET" && p === "/sdk/flags") {
        const flags = await listFlags();
        const etag = `"${Math.max(0, ...flags.map((f) => Number(f.version)))}"`;
        if (req.headers["if-none-match"] === etag) return send(res, 304, undefined, { etag });
        return send(res, 200, { flags: flags.map(forSdk) }, { etag });
      }
      if (m === "GET" && p === "/sdk/stream") {
        res.writeHead(200, { "content-type": "text/event-stream", "cache-control": "no-cache" });
        res.write(": terhubung\n\n");
        streams.add(res);
        req.on("close", () => streams.delete(res));
        return;
      }
      if (m === "POST" && p === "/events") {
        const events = validateBatch(await readJson(req));
        const accepted = await insertEvents(events);
        return send(res, 202, { accepted, duplicates: events.length - accepted });
      }

      const f = p.match(/^\/admin\/flags\/([^/]+)(\/kill|\/audit)?$/);
      if (p === "/admin/flags" || f) {
        const actor = adminActor(req);
        if (m === "GET" && !f) return send(res, 200, await listFlags());
        if (f && m === "PUT" && !f[2]) return send(res, 200, await putFlag(actor, f[1], await readJson(req)));
        if (f && m === "POST" && f[2] === "/kill") {
          const b = await readJson(req);
          return send(res, 200, await setKilled(actor, f[1], b?.killed !== false, b?.reason));
        }
        if (f && m === "GET" && f[2] === "/audit") return send(res, 200, await auditFor(f[1]));
      }
      send(res, 404, { error: "tidak ditemukan" });
    } catch (e) {
      if (e instanceof HttpError) return send(res, e.status, { error: e.message });
      console.error(e);
      send(res, 500, { error: "kesalahan server" });
    }
  });
}

import { pool } from "./db.ts";
import { createApp, listenForChanges } from "./server.ts";

if (process.env.NODE_ENV === "production" && (!process.env.SDK_KEY || !process.env.ADMIN_TOKENS)) {
  console.error("SDK_KEY dan ADMIN_TOKENS wajib diisi di production");
  process.exit(1);
}
// Tiap 6 jam: siapkan partisi bulan depan jauh sebelum dibutuhkan, dan segarkan statistik tabel
// induk (autovacuum hanya meng-ANALYZE partisi, tidak pernah induknya).
const maintenance = () => pool.query("SELECT ensure_event_partitions(); ANALYZE events;");
await maintenance();
setInterval(() => maintenance().catch(console.error), 6 * 3_600_000).unref();
await listenForChanges();

const port = Number(process.env.PORT ?? 3000);
createApp().listen(port, () => console.log(`eksperimen-ab siap di http://localhost:${port}`));

import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import type { AddressInfo } from "node:net";
import { after, before, test } from "node:test";
import { pool } from "../src/db.ts";
import { createApp } from "../src/server.ts";

const server = createApp();
let base = "";
before(() => new Promise<void>((ok) => server.listen(0, () => {
  base = `http://localhost:${(server.address() as AddressInfo).port}`;
  ok();
})));
