// SDK server-side: evaluasi flag di memori (tanpa jaringan per request),
// update lewat SSE atau polling, event dikirim per batch dengan event_id tetap.
import { randomUUID } from "node:crypto";
import { assign, pseudonym, type FlagConfig } from "../src/hash.ts";

export type ClientOptions = {
  baseUrl: string;
  sdkKey: string;
  unitSecret: string;           // rahasia HMAC untuk id pseudonim; sama di semua instance aplikasi
  mode?: "stream" | "poll";
  pollMs?: number;
  flushMs?: number;
  maxBatch?: number;
  maxQueue?: number;
};
type OutEvent = {
  event_id: string; ts: string; kind: "exposure" | "conversion"; unit: string;
  flag_key?: string; variant?: string; metric?: string; value?: number;
};

export class AbClient {
  private o: Required<ClientOptions>;
  private flags = new Map<string, FlagConfig>();
  private etag = "";
  private queue: OutEvent[] = [];
  private exposed = new Set<string>(); // ponytail: Set tanpa batas; ganti LRU kalau satu proses melihat jutaan unit
  private flushing = false;
  private timers: NodeJS.Timeout[] = [];
  private stop = new AbortController();
  dropped = 0;

  constructor(options: ClientOptions) {
    this.o = { mode: "stream", pollMs: 30_000, flushMs: 2_000, maxBatch: 200, maxQueue: 10_000, ...options };
  }

  async start(): Promise<void> {
    // Server mati saat start bukan alasan aplikasi ikut mati: semua flag jatuh ke fallback.
    await this.refresh().catch((e) => console.warn(`[ab] gagal memuat flag, pakai fallback: ${e.message}`));
    if (this.o.mode === "stream") void this.stream();
    else this.timers.push(setInterval(() => void this.refresh().catch(() => {}), this.o.pollMs));
    this.timers.push(setInterval(() => void this.flush(), this.o.flushMs));
  }

  /** Varian untuk user ini. Sinkron, tanpa I/O, aman dipanggil di jalur request. */
  variant(flagKey: string, userId: string, fallback = "control"): string {
    const flag = this.flags.get(flagKey);
    if (!flag) return fallback;
    const unit = pseudonym(this.o.unitSecret, userId);
    const a = assign(flag, unit);
    const seen = `${flagKey}:${unit}`;
    if (a.inExperiment && !this.exposed.has(seen)) {
      this.exposed.add(seen);
      this.push({ kind: "exposure", unit, flag_key: flagKey, variant: a.variant });
    }
    return a.variant;
  }

  /** Catat conversion, mis. track("checkout", userId, 125000). */
  track(metric: string, userId: string, value = 1): void {
    this.push({ kind: "conversion", unit: pseudonym(this.o.unitSecret, userId), metric, value });
  }

  async flush(): Promise<void> {
    if (this.flushing || this.queue.length === 0) return;
    this.flushing = true;
    const batch = this.queue.slice(0, this.o.maxBatch);
    try {
      const r = await fetch(`${this.o.baseUrl}/events`, {
        method: "POST",
        headers: { authorization: `Bearer ${this.o.sdkKey}`, "content-type": "application/json" },
        body: JSON.stringify({ events: batch }),
        signal: AbortSignal.timeout(10_000),
      });
      // 2xx: terkirim. 4xx selain 429: data rusak, mengulang tidak akan menolong.
      if (r.ok || (r.status >= 400 && r.status < 500 && r.status !== 429)) {
        if (!r.ok) console.warn(`[ab] batch ditolak ${r.status}: ${await r.text()}`);
        this.queue.splice(0, batch.length);
      }
    } catch {
      // Jaringan putus atau timeout: batch tetap di depan antrean dan dikirim ulang
      // dengan event_id yang SAMA. Server membuang duplikat, jadi at-least-once tetap benar.
    } finally {
      this.flushing = false;
    }
  }

  async close(): Promise<void> {
    this.stop.abort();
    this.timers.forEach(clearInterval);
    while (this.queue.length > 0) {
      const before = this.queue.length;
      await this.flush();
      if (this.queue.length >= before) break; // server tidak bisa dihubungi: jangan menggantung saat shutdown
    }
  }

  private push(e: Omit<OutEvent, "event_id" | "ts">): void {
    if (this.queue.length >= this.o.maxQueue) { this.dropped++; return; } // lindungi memori aplikasi
    this.queue.push({ event_id: randomUUID(), ts: new Date().toISOString(), ...e });
    if (this.queue.length >= this.o.maxBatch) void this.flush();
  }

  private async refresh(): Promise<void> {
    const r = await fetch(`${this.o.baseUrl}/sdk/flags`, {
      headers: { authorization: `Bearer ${this.o.sdkKey}`, "if-none-match": this.etag },
      signal: AbortSignal.timeout(5_000),
    });
    if (r.status === 304) return;
    if (!r.ok) throw new Error(`GET /sdk/flags ${r.status}`);
    const body = (await r.json()) as { flags: FlagConfig[] };
    this.flags = new Map(body.flags.map((f) => [f.key, f]));
    this.etag = r.headers.get("etag") ?? "";
  }

  private async stream(): Promise<void> {
    let wait = 1_000;
    while (!this.stop.signal.aborted) {
      try {
        const r = await fetch(`${this.o.baseUrl}/sdk/stream`, {
          headers: { authorization: `Bearer ${this.o.sdkKey}` }, signal: this.stop.signal,
        });
        if (!r.ok || !r.body) throw new Error(`stream ${r.status}`);
        await this.refresh(); // tutup celah: perubahan selama terputus tidak terlewat
        wait = 1_000;
        let buf = "";
        for await (const chunk of r.body.pipeThrough(new TextDecoderStream())) {
          buf += chunk;
          for (let i = buf.indexOf("\n\n"); i >= 0; i = buf.indexOf("\n\n")) {
            const message = buf.slice(0, i);
            buf = buf.slice(i + 2);
            if (message.startsWith("event: flags")) await this.refresh().catch(() => {});
          }
        }
      } catch {
        if (this.stop.signal.aborted) return;
      }
      await new Promise((ok) => setTimeout(ok, wait));
      wait = Math.min(wait * 2, 30_000); // backoff saat server tidak bisa dihubungi
    }
  }
}

