const waitFor = async (ok: () => boolean | Promise<boolean>, ms = 3_000) => {
  const t0 = Date.now();
  while (!(await ok())) {
    if (Date.now() - t0 > ms) throw new Error("timeout");
    await new Promise((r) => setTimeout(r, 20));
  }
  return Date.now() - t0;
};

