// Fungsi distribusi untuk uji statistik, tanpa dependensi.
// Rumus dari Numerical Recipes; nilainya dicek terhadap tabel di test/stats.test.ts.

// Distribusi normal baku. erfc pendekatan Chebyshev, galat < 1.2e-7.
export function normalCdf(z: number): number {
  const x = Math.abs(z) / Math.SQRT2, t = 1 / (1 + 0.5 * x);
  const erfc = t * Math.exp(-x * x - 1.26551223 + t * (1.00002368 + t * (0.37409196 + t * (0.09678418 +
    t * (-0.18628806 + t * (0.27886807 + t * (-1.13520398 + t * (1.48851587 + t * (-0.82215223 + t * 0.17087277)))))))));
  return z >= 0 ? 1 - erfc / 2 : erfc / 2;
}

// Cari x dengan bisection: cukup cepat untuk laporan, dan mustahil salah arah.
function invert(f: (x: number) => number, target: number, lo: number, hi: number): number {
  for (let i = 0; i < 100; i++) {
    const mid = (lo + hi) / 2;
    if (f(mid) < target) lo = mid; else hi = mid;
  }
  return (lo + hi) / 2;
}
export const normalQuantile = (p: number) => invert(normalCdf, p, -12, 12);

function lnGamma(x: number): number {
  const c = [76.18009172947146, -86.50532032941677, 24.01409824083091, -1.231739572450155, 0.1208650973866179e-2, -0.5395239384953e-5];
  let y = x, tmp = x + 5.5, ser = 1.000000000190015;
  tmp -= (x + 0.5) * Math.log(tmp);
  for (const ci of c) ser += ci / ++y;
  return -tmp + Math.log((2.5066282746310005 * ser) / x);
}

const TINY = 1e-300;
// Fungsi gamma tak lengkap atas teregularisasi Q(a, x).
function gammaQ(a: number, x: number): number {
  if (x <= 0) return 1;
  const front = Math.exp(-x + a * Math.log(x) - lnGamma(a));
  if (x < a + 1) { // deret
    let ap = a, sum = 1 / a, del = sum;
    for (let n = 0; n < 1000 && Math.abs(del) > Math.abs(sum) * 1e-15; n++) { del *= x / ++ap; sum += del; }
    return 1 - sum * front;
  }
  let b = x + 1 - a, c = 1 / TINY, d = 1 / b, h = d; // pecahan berlanjut (Lentz)
  for (let i = 1; i < 1000; i++) {
    const an = -i * (i - a);
    b += 2;
    d = an * d + b; if (Math.abs(d) < TINY) d = TINY;
    c = b + an / c; if (Math.abs(c) < TINY) c = TINY;
    d = 1 / d;
    h *= d * c;
    if (Math.abs(d * c - 1) < 1e-15) break;
  }
  return front * h;
}
export const chiSquareP = (x: number, df: number) => gammaQ(df / 2, x / 2);

function betaCf(a: number, b: number, x: number): number {
  const qab = a + b, qap = a + 1, qam = a - 1;
  let c = 1, d = 1 - (qab * x) / qap;
  if (Math.abs(d) < TINY) d = TINY;
  d = 1 / d;
  let h = d;
  for (let m = 1; m <= 1000; m++) {
    const m2 = 2 * m;
    for (const aa of [(m * (b - m) * x) / ((qam + m2) * (a + m2)), (-(a + m) * (qab + m) * x) / ((a + m2) * (qap + m2))]) {
      d = 1 + aa * d; if (Math.abs(d) < TINY) d = TINY;
      c = 1 + aa / c; if (Math.abs(c) < TINY) c = TINY;
      d = 1 / d;
      h *= d * c;
    }
    if (Math.abs(d * c - 1) < 1e-15) break;
  }
  return h;
}
// Fungsi beta tak lengkap teregularisasi I_x(a, b).
function betaI(a: number, b: number, x: number): number {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  const bt = Math.exp(lnGamma(a + b) - lnGamma(a) - lnGamma(b) + a * Math.log(x) + b * Math.log(1 - x));
  return x < (a + 1) / (a + b + 2) ? (bt * betaCf(a, b, x)) / a : 1 - (bt * betaCf(b, a, 1 - x)) / b;
}
// p-value dua sisi distribusi t Student.
export const tTwoSidedP = (t: number, df: number) => betaI(df / 2, 0.5, df / (df + t * t));
// Nilai kritis t untuk CI dengan tingkat `level` (mis. 0.95).
export const tCritical = (level: number, df: number) => invert((t) => 1 - tTwoSidedP(t, df), level, 0, 1e4);

import { chiSquareP, normalCdf, normalQuantile, tCritical, tTwoSidedP } from "./stats.ts";

// Statistik cukup per varian: semua uji di bawah hanya butuh jumlah-jumlah ini,
// jadi Postgres yang menjumlah jutaan baris, Node hanya menghitung belasan angka.
// y = metrik selama eksperimen, x = metrik yang sama sebelum unit ter-expose (kovariat CUPED).
export type Sums = { n: number; sy: number; syy: number; sx: number; sxx: number; sxy: number };
export type Estimate = { control: number; treatment: number; diff: number; lo: number; hi: number; p: number; rel: number };

const cov = (sab: number, sa: number, sb: number, n: number) => (sab - (sa * sb) / n) / (n - 1);

// Sample Ratio Mismatch: apakah jumlah unit per varian cocok dengan bobot? Chi-square goodness of fit.
export function srm(observed: number[], weights: number[]): { chi2: number; p: number; ok: boolean } {
  const total = observed.reduce((a, b) => a + b, 0), wsum = weights.reduce((a, b) => a + b, 0);
  const chi2 = observed.reduce((s, o, i) => {
    const e = (total * weights[i]) / wsum;
    return s + (o - e) ** 2 / e;
  }, 0);
  const p = chiSquareP(chi2, observed.length - 1);
  return { chi2, p, ok: p >= 0.001 }; // ambang ketat: SRM diperiksa di setiap eksperimen
}

// Uji dua proporsi. Uji H0 memakai SE gabungan (pooled); CI memakai SE tak gabungan.
export function twoProportion(x1: number, n1: number, x2: number, n2: number, level = 0.95): Estimate {
  const p1 = x1 / n1, p2 = x2 / n2, pooled = (x1 + x2) / (n1 + n2), diff = p2 - p1;
  const seH0 = Math.sqrt(pooled * (1 - pooled) * (1 / n1 + 1 / n2));
  const se = Math.sqrt((p1 * (1 - p1)) / n1 + (p2 * (1 - p2)) / n2);
  const q = normalQuantile(1 - (1 - level) / 2);
  const p = seH0 > 0 ? 2 * (1 - normalCdf(Math.abs(diff / seH0))) : 1;
  return { control: p1, treatment: p2, diff, lo: diff - q * se, hi: diff + q * se, p, rel: diff / p1 };
}

// Welch t-test: tidak mengasumsikan varians kedua grup sama.
export function welch(m1: number, v1: number, n1: number, m2: number, v2: number, n2: number, level = 0.95): Estimate {
  const a = v1 / n1, b = v2 / n2, se = Math.sqrt(a + b), diff = m2 - m1;
  const df = (a + b) ** 2 / ((a * a) / (n1 - 1) + (b * b) / (n2 - 1));
  const q = tCritical(level, df);
  return { control: m1, treatment: m2, diff, lo: diff - q * se, hi: diff + q * se, p: se > 0 ? tTwoSidedP(diff / se, df) : 1, rel: diff / m1 };
}

export const welchFromSums = (c: Sums, t: Sums, level = 0.95) =>
  welch(c.sy / c.n, cov(c.syy, c.sy, c.sy, c.n), c.n, t.sy / t.n, cov(t.syy, t.sy, t.sy, t.n), t.n, level);

// CUPED: y' = y - theta * (x - mean(x)), theta = cov(x, y) / var(x) dari data gabungan.
// Rata-rata y' sama dengan y (estimasi tetap tak bias), tetapi variansnya turun sebesar korelasi^2.
export function cuped(c: Sums, t: Sums, level = 0.95): Estimate & { theta: number; varianceReduction: number } {
  const all = { n: c.n + t.n, sy: c.sy + t.sy, sx: c.sx + t.sx, sxx: c.sxx + t.sxx, sxy: c.sxy + t.sxy };
  const vxAll = cov(all.sxx, all.sx, all.sx, all.n);
  const theta = vxAll > 0 ? cov(all.sxy, all.sx, all.sy, all.n) / vxAll : 0;
  const mx = all.sx / all.n;
  const adjust = (s: Sums) => {
    const vy = cov(s.syy, s.sy, s.sy, s.n), vx = cov(s.sxx, s.sx, s.sx, s.n), cxy = cov(s.sxy, s.sx, s.sy, s.n);
    return { mean: s.sy / s.n - theta * (s.sx / s.n - mx), v: vy - 2 * theta * cxy + theta * theta * vx, raw: vy };
  };
  const a = adjust(c), b = adjust(t);
  const est = welch(a.mean, a.v, c.n, b.mean, b.v, t.n, level);
  return { ...est, rel: est.diff / (c.sy / c.n), theta, varianceReduction: 1 - (a.v + b.v) / (a.raw + b.raw) };
}

import { normalQuantile } from "./stats.ts";

const z = (alpha: number, power: number) => normalQuantile(1 - alpha / 2) + normalQuantile(power);

// Unit per varian untuk mendeteksi selisih absolut `mde` dari baseline proporsi `base`.
export function sampleSizeProportion(base: number, mde: number, alpha = 0.05, power = 0.8): number {
  const p2 = base + mde;
  return Math.ceil((z(alpha, power) ** 2 * (base * (1 - base) + p2 * (1 - p2))) / mde ** 2);
}

// Unit per varian untuk metrik rata-rata dengan simpangan baku `sd`.
// CUPED yang mengurangi varians sebesar r membuat kebutuhan unit turun dengan faktor (1 - r).
export function sampleSizeMean(sd: number, mde: number, alpha = 0.05, power = 0.8, varianceReduction = 0): number {
  return Math.ceil((2 * z(alpha, power) ** 2 * sd ** 2 * (1 - varianceReduction)) / mde ** 2);
}

import { pool } from "../db.ts";
import type { Metric } from "../flags.ts";
import { HttpError } from "../http.ts";
import { cuped, srm, twoProportion, welchFromSums, type Sums } from "./tests.ts";

// Unit pertama kali ter-expose = awal pengamatannya. Unit yang melihat >1 varian dibuang (dan dihitung).
const EXPOSED = `
  SELECT unit, min(variant) AS variant, count(DISTINCT variant) AS nv, min(ts) AS first_ts
  FROM events WHERE kind = 'exposure' AND flag_key = $1 GROUP BY unit`;

// Per unit: y = metrik setelah exposure, x = metrik 14 hari sebelum exposure. Lalu dijumlah per varian.
const SUMS = `
  WITH e AS (${EXPOSED}),
  u AS (
    SELECT e.variant,
      count(c.event_id) FILTER (WHERE c.ts >= e.first_ts) AS y_cnt,
      coalesce(sum(c.value) FILTER (WHERE c.ts >= e.first_ts), 0) AS y_sum,
      count(c.event_id) FILTER (WHERE c.ts < e.first_ts) AS x_cnt,
      coalesce(sum(c.value) FILTER (WHERE c.ts < e.first_ts), 0) AS x_sum
    FROM e LEFT JOIN events c
      ON c.kind = 'conversion' AND c.metric = $2 AND c.unit = e.unit AND c.ts >= e.first_ts - interval '14 days'
    WHERE e.nv = 1
    GROUP BY e.unit, e.variant
  ),
  m AS (
    SELECT variant,
      CASE WHEN $3 = 'binomial' THEN (y_cnt > 0)::int ELSE y_sum END::float8 AS y,
      CASE WHEN $3 = 'binomial' THEN (x_cnt > 0)::int ELSE x_sum END::float8 AS x
    FROM u
  )
  SELECT variant, count(*)::float8 AS n, sum(y) AS sy, sum(y * y) AS syy,
         sum(x) AS sx, sum(x * x) AS sxx, sum(x * y) AS sxy
  FROM m GROUP BY variant`;

export async function analyze(flagKey: string, level = 0.95) {
  const { rows: [flag] } = await pool.query(
    "SELECT key, status, killed, variants, default_variant, metrics FROM flags WHERE key = $1", [flagKey]);
  if (!flag) throw new HttpError(404, "flag tidak ditemukan");

  const { rows: units } = await pool.query(
    `SELECT variant, count(*) FILTER (WHERE nv = 1)::int AS n, count(*) FILTER (WHERE nv > 1)::int AS multi
     FROM (${EXPOSED}) e GROUP BY variant`, [flagKey]);
  const variants: { key: string; weight: number }[] = flag.variants;
  const counts = variants.map((v) => units.find((r) => r.variant === v.key)?.n ?? 0);
  const ratio = srm(counts, variants.map((v) => v.weight));
  const control = flag.default_variant as string;

  const metrics = [];
  for (const metric of flag.metrics as Metric[]) {
    const { rows } = await pool.query(SUMS, [flagKey, metric.event, metric.type]);
    const sums = new Map<string, Sums>(rows.map((r) => [r.variant, r]));
    const c = sums.get(control);
    const comparisons = [];
    for (const v of variants.filter((v) => v.key !== control)) {
      const t = sums.get(v.key);
      if (!c || !t || c.n < 2 || t.n < 2) continue;
      const raw = metric.type === "binomial" ? twoProportion(c.sy, c.n, t.sy, t.n, level) : welchFromSums(c, t, level);
      const adj = cuped(c, t, level);
      // Keputusan memakai CI CUPED: "lebih baik" / "lebih buruk" hanya kalau CI tidak memuat 0.
      const good = metric.better === "higher" ? adj.lo > 0 : adj.hi < 0;
      const bad = metric.better === "higher" ? adj.hi < 0 : adj.lo > 0;
      const verdict = good ? "lebih baik" : bad ? "lebih buruk" : "belum jelas";
      comparisons.push({ variant: v.key, raw, cuped: adj, verdict });
    }
    metrics.push({ ...metric, comparisons });
  }

  const harmed = metrics.filter((m) => m.role === "guardrail" && m.comparisons.some((x) => x.verdict === "lebih buruk"));
  return {
    flag: flag.key, status: flag.status, killed: flag.killed, level,
    units: Object.fromEntries(variants.map((v, i) => [v.key, counts[i]])),
    multi_variant_units: units.reduce((s, r) => s + r.multi, 0),
    srm: ratio,
    metrics,
    warnings: [
      ...(ratio.ok ? [] : ["SRM: pembagian unit tidak sesuai bobot. Cari bug sebelum membaca hasil apa pun."]),
      ...harmed.map((m) => `Guardrail ${m.key} memburuk secara signifikan.`),
    ],
  };
}

