    n: s.n + 1, sy: s.sy + y, syy: s.syy + y * y, sx: s.sx + x, sxx: s.sxx + x * x, sxy: s.sxy + x * y,
  }), { n: 0, sy: 0, syy: 0, sx: 0, sxx: 0, sxy: 0 });
