// mulberry32: PRNG kecil yang bisa diberi seed, supaya simulasi bisa diulang persis.
export function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), a | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Eksperimen sintetis dengan efek BENAR yang diketahui, dikirim lewat API sungguhan.
//   node scripts/simulate.ts <flag-key> [jumlah-unit] [--broken]
import { randomUUID } from "node:crypto";
import { pool } from "../src/db.ts";
import { assign, pseudonym, type FlagConfig } from "../src/hash.ts";
import { rng } from "./rng.ts";

// Model perilaku: tiap unit punya kecenderungan beli p = 0,5 x u^2 (u acak 0..1) dan nilai belanja khas
// 50.000-150.000. Selama eksperimen ada K kesempatan checkout; treatment menaikkan peluang tiap kesempatan
// sebesar LIFT. Itulah efek yang ditanam, jadi nilai benarnya bisa dihitung, bukan ditebak:
const K = 4, LIFT = 0.01, PRE = 8;
const propensity = (u: number) => 0.5 * u * u;
export const TRUTH = {
  // P(>= 1 checkout) treatment - control, dirata-rata atas u (integral numerik): sekitar +0,0249
  checkout: Array.from({ length: 10_000 }, (_, j) => {
    const p = propensity((j + 0.5) / 10_000);
    return (1 - p) ** K - (1 - p - LIFT) ** K;
  }).reduce((a, b) => a + b) / 10_000,
  // Pendapatan per unit: K x LIFT x rata-rata nilai belanja = 4 x 0,01 x 100.000
  revenue: K * LIFT * 100_000,
};

type Options = { baseUrl: string; flagKey: string; n: number; broken?: number; seed?: number; adminToken?: string; sdkKey?: string };

export async function simulate(o: Options): Promise<{ events: number }> {
  const admin = o.adminToken ?? process.env.ADMIN_TOKEN ?? "admin-dev-token";
  const sdk = o.sdkKey ?? process.env.SDK_KEY ?? "sdk-dev-key";
  const r = await fetch(`${o.baseUrl}/admin/flags/${o.flagKey}`, {
    method: "PUT",
    headers: { authorization: `Bearer ${admin}`, "content-type": "application/json" },
    body: JSON.stringify({
      description: "Simulasi: tombol checkout hijau", status: "running", traffic_bp: 10_000, default_variant: "control",
      variants: [{ key: "control", weight: 5000 }, { key: "treatment", weight: 5000 }],
      metrics: [
        { key: "checkout", event: "checkout", type: "binomial", role: "primary", better: "higher" },
        { key: "revenue", event: "checkout", type: "mean", role: "secondary", better: "higher" },
        { key: "error", event: "error", type: "binomial", role: "guardrail", better: "lower" },
      ],
      reason: "simulasi efek yang diketahui",
    }),
  });
  if (!r.ok) throw new Error(`PUT flag ${r.status}: ${await r.text()}`);
  const flag = (await r.json()) as FlagConfig;

  const rand = rng(o.seed ?? 42), H = 3_600_000, D = 24 * H, now = Date.now();
  const events: object[] = [];
  const ev = (ts: number, e: object) => events.push({ event_id: randomUUID(), ts: new Date(ts).toISOString(), ...e });
  for (let i = 0; i < o.n; i++) {
    // Tiap simulasi = dunia sendiri dengan user sendiri. Kalau user dipakai ulang, checkout dari
    // simulasi lain ikut terhitung (conversion tidak terikat flag) dan efeknya tercampur.
    const unit = pseudonym("simulasi", `${o.flagKey}/user-${i}`);
    const { variant } = assign(flag, unit);
    const p = propensity(rand()), basket = 50_000 + 100_000 * rand();
    const checkout = (ts: number) => ev(ts, { kind: "conversion", unit, metric: "checkout", value: basket * (0.8 + 0.4 * rand()) });
    const exposedAt = now - 5 * D + 2 * D * rand();
    // Riwayat 14 hari sebelum exposure: bahan kovariat CUPED. Tidak dipengaruhi varian.
    for (let k = 0; k < PRE; k++) if (rand() < p) checkout(exposedAt - (1 + 12 * rand()) * D);
    // Bug yang disengaja: sebagian exposure treatment hilang (mis. halaman baru crash sebelum SDK mencatat).
    if (o.broken && variant === "treatment" && rand() < o.broken) continue;
    ev(exposedAt, { kind: "exposure", unit, flag_key: o.flagKey, variant });
    const lift = variant === "treatment" ? LIFT : 0;
    for (let k = 0; k < K; k++) if (rand() < p + lift) checkout(exposedAt + 2 * D * rand());
    if (rand() < 0.01) ev(exposedAt + H * rand(), { kind: "conversion", unit, metric: "error", value: 1 });
  }

  for (let i = 0; i < events.length; i += 500) {
    const res = await fetch(`${o.baseUrl}/events`, {
      method: "POST",
      headers: { authorization: `Bearer ${sdk}`, "content-type": "application/json" },
      body: JSON.stringify({ events: events.slice(i, i + 500) }),
    });
    if (res.status !== 202) throw new Error(`POST /events ${res.status}: ${await res.text()}`);
  }
  // Setelah muat massal, segarkan statistik planner. Autovacuum tidak pernah meng-ANALYZE
  // tabel induk berpartisi, jadi tanpa ini rencana query analisis bisa buruk.
  await pool.query("ANALYZE events");
  return { events: events.length };
}

