// Simulasi A/A (tidak ada efek sama sekali): seberapa sering kita "menemukan" efek?
//   node scripts/peeking.ts [jumlah-eksperimen]
import { twoProportion } from "../src/analysis/tests.ts";
import { rng } from "./rng.ts";

// Batas Pocock untuk 10 kali intip, alpha total 0,05 dua sisi: |z| > 2,555 (p < 0,0106).
export const POCOCK_P_10 = 0.0106;

export function peekingSim(sims = 2000, looks = 10, perLook = 1000, base = 0.1, seed = 1) {
  const rand = rng(seed);
  let fixed = 0, peek = 0, pocock = 0;
  for (let s = 0; s < sims; s++) {
    let x1 = 0, x2 = 0, n = 0, peekHit = false, pocockHit = false;
    for (let k = 1; k <= looks; k++) {
      for (let i = 0; i < perLook; i++) {
        if (rand() < base) x1++;
        if (rand() < base) x2++;
      }
      n += perLook;
      const { p } = twoProportion(x1, n, x2, n);
      if (p < 0.05) peekHit = true;         // berhenti di intipan pertama yang "signifikan"
      if (p < POCOCK_P_10) pocockHit = true; // ambang yang sudah dikoreksi untuk 10 intipan
      if (k === looks && p < 0.05) fixed++;  // hanya melihat sekali, di akhir
    }
    if (peekHit) peek++;
    if (pocockHit) pocock++;
  }
  return { sims, looks, fixed: fixed / sims, peek: peek / sims, pocock: pocock / sims };
}

if (import.meta.main) {
  const r = peekingSim(Number(process.argv[2] ?? 2000));
  const pct = (x: number) => `${(x * 100).toFixed(1)}%`;
  console.log(`${r.sims} eksperimen A/A, ${r.looks} kali intip, alpha nominal 5%`);
  console.table({
    "sekali di akhir (fixed horizon)": { "positif palsu": pct(r.fixed) },
    "intip tiap hari, stop saat p<0,05": { "positif palsu": pct(r.peek) },
    "intip tiap hari, batas Pocock": { "positif palsu": pct(r.pocock) },
  });
}

