  assert.ok(r.srm.ok, `SRM p=${r.srm.p}`);
  assert.equal(r.multi_variant_units, 0);
  for (const [key, truth] of Object.entries(TRUTH)) {
    const c = comparison(r, key);
    console.log(key, { truth, raw: [c.raw.lo, c.raw.hi], cuped: [c.cuped.lo, c.cuped.hi], reduksi: c.cuped.varianceReduction });
    assert.ok(c.raw.lo <= truth && truth <= c.raw.hi, `${key}: efek benar di luar CI mentah`);
    assert.ok(c.cuped.lo <= truth && truth <= c.cuped.hi, `${key}: efek benar di luar CI CUPED`);
    assert.ok(c.cuped.hi - c.cuped.lo < c.raw.hi - c.raw.lo, `${key}: CUPED harus mempersempit CI`);
  }
  assert.notEqual(comparison(r, "error").verdict, "lebih buruk");
  assert.deepEqual(r.warnings, []);
});

